function seeded(seed){ let x=Math.abs(hashCode(seed))||12345; return ()=>{x=(x*1664525+1013904223)%4294967296;return x/4294967296}; }
function hashCode(s){let h=0;for(let i=0;i<String(s).length;i++){h=((h<<5)-h)+String(s).charCodeAt(i);h|=0}return h}
function uuid(prefix='DS'){return `${prefix}-${Date.now().toString(36).toUpperCase()}-${Math.floor(Math.random()*1e5).toString(36).toUpperCase()}`}
function deepClone(x){return JSON.parse(JSON.stringify(x))}

