function save(){
  profiles[activeId]=state;
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(profiles));localStorage.setItem(ACTIVE_KEY,activeId)}catch(e){toast('Storage limit reached','Export your profile to preserve it.','warn')}
}
function ensureDemoAssets(){ if(state.kind==='demo' && !state.assets.length){state.assets=deriveAssets(state);seedDemoHistory();save()} }
function switchProfile(id){if(!profiles[id])return;activeId=id;state=profiles[id];localStorage.setItem(ACTIVE_KEY,id);ensureDemoAssets();renderChrome();go('overview');toast('Profile switched',state.name)}

function deriveAssets(profile=state){
  const assets=[]; const srcs=Object.values(profile.sources||{});
  for(const src of srcs){
    if(src.type==='spotify'){
      const hours=src.metadata?.hours||Math.round(src.records/5); const artists=src.metadata?.artists||Math.max(20,Math.round(src.records/12));
      assets.push(makeAsset('entertainment','Music affinity',src,clamp(52+Math.log10(src.records+1)*8,20,96),clamp(45+artists/10,20,95),clamp(50+hours/20,20,96),.92));
      assets.push(makeAsset('athletics','Activity soundtrack pattern',src,clamp(42+hours/30,20,90),clamp(55+artists/14,20,90),72,.72));
    }else if(src.type==='tiktok'){
      const likes=src.metadata?.likes||Math.round(src.records*.18); const cats=src.metadata?.categories||7;
      assets.push(makeAsset('social','Engagement pattern',src,clamp(55+Math.log10(src.records+1)*8,20,96),clamp(50+cats*4,20,92),clamp(55+likes/40,20,94),.86));
      assets.push(makeAsset('entertainment','Short-form content affinity',src,clamp(56+cats*3,20,95),clamp(48+cats*5,20,95),80,.88));
    }else if(src.type==='generic'){
      const domain=src.metadata?.domain||'social'; const diversity=src.metadata?.diversity||Math.min(20,src.records);
      assets.push(makeAsset(domain,src.metadata?.assetName||'Imported behavioral signal',src,clamp(48+Math.log10(src.records+1)*10,20,95),clamp(45+diversity*2.2,20,94),68,.78));
    }else if(src.type==='manual'){
      const domain=src.metadata?.domain||'athletics';
      assets.push(makeAsset(domain,src.metadata?.assetName||'Self-reported preference profile',src,70,62,66,.64));
    }
  }
  if(!assets.length) return [];
  const merged=[];
  for(const a of assets){const prev=merged.find(x=>x.name===a.name&&x.domain===a.domain);if(prev){prev.signalCount+=a.signalCount;prev.confidence=clamp((prev.confidence+a.confidence)/2+3,0,99);prev.sources.push(...a.sources)}else merged.push(a)}
  return merged.map(a=>revalueAsset(a,profile));
}
function makeAsset(domain,name,src,freshness,rarity,demand,confidence){
  return {id:`asset-${domain}-${name.toLowerCase().replace(/\W+/g,'-')}`,domain,name,signalCount:src.records||1,freshness,rarity,demand,confidence:Math.round(confidence*100),sources:[src.id],createdAt:src.importedAt||nowISO(),lastUpdated:src.importedAt||nowISO(),value:0,risk:DOMAIN_META[domain].riskScore,yield:0,depreciation:1};
}
function ageWeeks(iso){return Math.max(0,(Date.now()-new Date(iso).getTime())/(1000*60*60*24*7))}
function depreciation(iso){return Math.max(.3,1-(.08*ageWeeks(iso)))}
function revalueAsset(a,profile=state){
  const b=DS.domainBenchmarks[a.domain];
  const dep=depreciation(a.lastUpdated); const cbs=(a.freshness+a.rarity+a.demand+clamp(a.confidence,0,100))/4;
  const privacyPremium=1+(b.riskWeight*.12); const quality=0.7+(a.confidence/100)*.35; const scale=Math.max(1,Math.log10((a.signalCount||1)+10));
  const unit=b.baseRate*(.5+cbs/100)*dep*b.demandIndex*privacyPremium*quality;
  const value=unit*scale*2.75;
  return {...a,cbs:+cbs.toFixed(1),depreciation:+dep.toFixed(3),modeledUnitPrice:+unit.toFixed(4),value:+value.toFixed(3),yield:+((b.demandIndex*.8+dep*.7)*2.1).toFixed(1)};
}
function portfolio(){
  state.assets=(state.assets||[]).map(a=>revalueAsset(a));
  const modeled=state.assets.reduce((s,a)=>s+a.value,0); const realized=state.transactions.filter(t=>t.status==='approved').reduce((s,t)=>s+t.finalPrice,0);
  const risk=state.assets.length?state.assets.reduce((s,a)=>s+a.risk*(a.value||.1),0)/(modeled||1):0;
  const diversity=clamp(new Set(state.assets.map(a=>a.domain)).size/6*100 + Math.min(20,state.assets.length*3),0,100);
  const freshness=state.assets.length?state.assets.reduce((s,a)=>s+a.freshness,0)/state.assets.length:0;
  const control=DOMAIN_KEYS.reduce((s,k)=>s+({open:60,selective:82,locked:98}[state.domains[k].status]||70),0)/6;
  const score=Math.round(clamp((100-risk)*.3+diversity*.16+freshness*.18+control*.26+Math.min(100,state.ledger.length*4)*.10,0,100));
  return {modeled:+modeled.toFixed(2),realized:+realized.toFixed(3),risk:+risk.toFixed(1),diversity:Math.round(diversity),freshness:Math.round(freshness),control:Math.round(control),score};
}

function seedDemoHistory(){
  if(state.transactions.length)return;
  const scenarios=syntheticRequests();
  const chosen=[scenarios[0],scenarios[2],scenarios[4]];
  chosen.forEach((r,i)=>{
    const t=executeTransaction(r,{silent:true,at:new Date(Date.now()-1000*60*60*24*(7-i*2)).toISOString(),force:true});
    if(i===1&&t)t.negotiated=true;
  });
  state.portfolioHistory=[];
  for(let i=13;i>=0;i--){const rand=seeded('history'+i);state.portfolioHistory.push({date:new Date(Date.now()-i*86400000).toISOString(),value:+(3.1+(13-i)*.09+rand()*.45).toFixed(2),realized:+(state.transactions.filter(t=>new Date(t.createdAt)<=new Date(Date.now()-i*86400000)).reduce((s,t)=>s+t.finalPrice,0)).toFixed(3)})}
  generateRecommendations(true);
}

function syntheticRequests(){
  const bases=[
    ['Stride Research','Sports research','athletics','Athletic interest + purchase intent','Market research',.11,88,79,93,84],
    ['StreamLab','Media analytics','entertainment','Genre affinity + viewing patterns','Market research',.07,94,67,81,72],
    ['Campus Trends Lab','Academic research','social','Engagement timing + content categories','Academic research',.10,81,72,76,69],
    ['Mobility Insights','Urban analytics','location','Regional mobility pattern','Market research',.20,86,83,90,88],
    ['Consumer Signal Co.','Consumer research','finance','Purchase-category propensity','Market research',.16,89,81,91,86],
    ['Wellness Research Lab','Research','health','Aggregate activity-intensity band','Academic research',.19,84,78,82,79]
  ];
  return bases.map((x,i)=>({id:`REQ-${i+1}`,buyer:x[0],industry:x[1],domain:x[2],data:x[3],purpose:x[4],offer:x[5],recency:x[6],exclusivity:x[7],demand:x[8],rarity:x[9],retention:[30,30,14,7,14,7][i],synthetic:true,createdAt:new Date(Date.now()-i*3600000*2).toISOString()}));
}
function requestScore(r){return +((r.recency+r.exclusivity+r.demand+r.rarity)/4).toFixed(1)}
function requestPrice(r){const b=DS.domainBenchmarks[r.domain];const policy=state.domains[r.domain];const cbs=requestScore(r);const dep=.94;const model=b.baseRate*(.5+cbs/100)*dep*b.demandIndex*(1+b.riskWeight*.10);return +Math.max(model,policy.floor||0).toFixed(3)}
function evaluateRequest(r){
  const policy=state.domains[r.domain]; const reasons=[];
  if(policy.status==='locked')reasons.push(`${DOMAIN_META[r.domain].name} is locked`);
  if(!policy.purposes.map(x=>x.toLowerCase()).some(x=>r.purpose.toLowerCase().includes(x.split('-')[0]))) reasons.push('Purpose not on allow-list');
  if(r.retention>policy.retention)reasons.push(`Retention ${r.retention}d exceeds ${policy.retention}d policy`);
  const fair=requestPrice(r); const offer=r.offer; const verdict=reasons.length?'deny':offer>=fair?'approve':'negotiate';
  return {verdict,fair,offer,reasons,cbs:requestScore(r),policy};
}

function transformPackage(domain,noise=state.settings.noise,seed=Date.now()){
  const rand=seeded(`${domain}:${noise}:${seed}`); const probability=noise/100*.9;
  const base={age_band:'15–24',region:'Central Virginia',interest_score:87,weekly_activity_hours:6.8,last_event:'2026-08-15T19:42:18',device_type:'mobile',account_id:'usr_2f8a91',precise_location:'37.54,-77.43'};
  const out={}; const actions=[];
  Object.entries(base).forEach(([k,v])=>{
    if(['account_id','precise_location'].includes(k)){out[k]='BLOCKED';actions.push({field:k,action:'blocked'});return}
    if(rand()<probability){
      if(typeof v==='number')out[k]=+(v+(rand()-.5)*Math.max(1,v*.12)).toFixed(1);
      else if(k==='last_event')out[k]=v.slice(0,13)+':00:00';
      else if(k==='region')out[k]='Virginia (coarse)';
      else out[k]=v;
      actions.push({field:k,action:'transformed'});
    } else {out[k]=v;actions.push({field:k,action:'retained'})}
  });
  const blocked=actions.filter(a=>a.action==='blocked').length, transformed=actions.filter(a=>a.action==='transformed').length;
  const utility=Math.round(clamp(100-noise*.38-blocked*2,48,98)); const risk=Math.round(clamp(72-noise*.65-blocked*12,5,80));
  return {original:base,protected:out,actions,utility,risk,transformed,blocked,seed:String(seed)};
}

async function sha256(text){
  if(window.crypto?.subtle){const data=new TextEncoder().encode(text);const hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
  // Standards-compatible pure-JS SHA-256 fallback for non-secure/file contexts.
  const rightRotate=(value,amount)=>(value>>>amount)|(value<<(32-amount));
  const maxWord=Math.pow(2,32),result=[];let words=[],ascii=unescape(encodeURIComponent(String(text))),asciiBitLength=ascii.length*8,hash=[],k=[],primeCounter=0,isComposite={};
  for(let candidate=2;primeCounter<64;candidate++){if(!isComposite[candidate]){for(let i=0;i<313;i+=candidate)isComposite[i]=candidate;hash[primeCounter]=(Math.pow(candidate,.5)*maxWord)|0;k[primeCounter++]=(Math.pow(candidate,1/3)*maxWord)|0}}
  ascii+='\x80';while(ascii.length%64-56)ascii+='\x00';for(let i=0;i<ascii.length;i++){const j=ascii.charCodeAt(i);words[i>>2]|=j<<((3-i)%4)*8}words[words.length]=(asciiBitLength/maxWord)|0;words[words.length]=asciiBitLength;
  for(let j=0;j<words.length;){const w=words.slice(j,j+=16),oldHash=hash.slice(0);hash=hash.slice(0,8);for(let i=0;i<64;i++){const w15=w[i-15],w2=w[i-2],a=hash[0],e=hash[4];const temp1=(hash[7]+(rightRotate(e,6)^rightRotate(e,11)^rightRotate(e,25))+((e&hash[5])^((~e)&hash[6]))+k[i]+(w[i]=(i<16)?w[i]:((w[i-16]+(rightRotate(w15,7)^rightRotate(w15,18)^(w15>>>3))+w[i-7]+(rightRotate(w2,17)^rightRotate(w2,19)^(w2>>>10)))|0)))|0;const temp2=((rightRotate(a,2)^rightRotate(a,13)^rightRotate(a,22))+((a&hash[1])^(a&hash[2])^(hash[1]&hash[2])))|0;hash=[(temp1+temp2)|0,a,hash[1],hash[2],(hash[3]+temp1)|0,hash[4],hash[5],hash[6]]}for(let i=0;i<8;i++)hash[i]=(hash[i]+oldHash[i])|0}
  for(let i=0;i<8;i++)for(let j=3;j+1;j--){const b=(hash[i]>>(j*8))&255;result.push((b<16?'0':'')+b.toString(16))}return result.join('');
}
let ledgerQueue=Promise.resolve();
function appendLedger(record){
  ledgerQueue=ledgerQueue.then(async()=>{
    const prev=state.ledger.length?state.ledger[state.ledger.length-1].hash:'GENESIS';
    const base={id:record.id||uuid('LED'),createdAt:record.createdAt||nowISO(),type:record.type||'transaction',subject:record.subject||'',status:record.status||'recorded',amount:record.amount||0,domain:record.domain||'',previousHash:prev,payload:record.payload||{}};
    base.hash=await sha256(JSON.stringify({...base,hash:undefined})); state.ledger.push(base);save();return base;
  });
  return ledgerQueue;
}
async function verifyLedger(){
  for(let i=0;i<state.ledger.length;i++){
    const e=state.ledger[i],prev=i?state.ledger[i-1].hash:'GENESIS'; if(e.previousHash!==prev)return {ok:false,index:i};
    const expected=await sha256(JSON.stringify({...e,hash:undefined})); if(expected!==e.hash)return {ok:false,index:i};
  } return {ok:true,count:state.ledger.length};
}

function executeTransaction(r,opts={}){
  const ev=evaluateRequest(r); if(ev.verdict==='deny'&&!opts.force){addActivity('Request blocked',`${r.buyer} · ${ev.reasons.join(', ')}`,'blocked');return null}
  const finalPrice=opts.force?Math.max(ev.fair,r.offer):ev.verdict==='negotiate'?+(ev.fair*1.04).toFixed(3):r.offer;
  const shield=transformPackage(r.domain,state.settings.noise,opts.at||Date.now());
  const t={id:uuid('TX'),requestId:r.id,buyer:r.buyer,domain:r.domain,purpose:r.purpose,synthetic:r.synthetic!==false,createdAt:opts.at||nowISO(),offer:r.offer,fairPrice:ev.fair,finalPrice,status:'approved',cbs:ev.cbs,shield:{noise:state.settings.noise,utility:shield.utility,risk:shield.risk,transformed:shield.transformed,blocked:shield.blocked},license:{retention:Math.min(r.retention,ev.policy.retention),purpose:r.purpose,rawDataReleased:false},dataPackage:shield.protected};
  state.transactions.unshift(t);
  const receipt={id:uuid('RCP'),transactionId:t.id,createdAt:t.createdAt,buyer:t.buyer,domain:t.domain,purpose:t.purpose,requestedFields:Object.keys(shield.original).length,releasedFields:Object.values(shield.protected).filter(v=>v!=='BLOCKED').length,blockedFields:shield.blocked,transformedFields:shield.transformed,offer:t.offer,finalPrice:t.finalPrice,retention:t.license.retention,synthetic:t.synthetic};
  state.receipts.unshift(receipt); addActivity('Protected exchange executed',`${t.buyer} · ${money(t.finalPrice)} · raw data not released`,'approved',t.createdAt);
  appendLedger({id:`LED-${t.id}`,createdAt:t.createdAt,type:'transaction',subject:t.buyer,status:'approved',amount:t.finalPrice,domain:t.domain,payload:{requestId:t.requestId,shield:t.shield,license:t.license}}).then(()=>save());
  if(!opts.silent){toast('Transaction completed',`${money(t.finalPrice)} modeled proceeds · protected package delivered`);generateRecommendations();}
  save();return t;
}
function addActivity(title,detail,type='info',at=nowISO()){state.activity.unshift({id:uuid('ACT'),title,detail,type,createdAt:at});state.activity=state.activity.slice(0,100);if(state.settings.notifications){state.notifications.unshift({id:uuid('N'),title,detail,read:false,createdAt:at});state.notifications=state.notifications.slice(0,50)}save()}

function generateRecommendations(silent=false){
  const p=portfolio(); const recs=[];
  if(state.assets.length===0)recs.push({id:'connect',type:'Portfolio',title:'Build your first real data asset',text:'Import a supported export or a generic CSV/JSON file. DataShadow will derive inspectable signals and replace empty modeled values with calculations tied to those inputs.',impact:'Foundation',action:'vault'});
  if(p.freshness<72&&state.assets.length)recs.push({id:'fresh',type:'Freshness',title:'Refresh aging data sources',text:`Portfolio freshness is ${p.freshness}/100. Refreshing the oldest source would improve the time-depreciation factor used by the pricing model.`,impact:'+ modeled value',action:'vault'});
  const openHigh=DOMAIN_KEYS.find(k=>state.domains[k].status!=='locked'&&DOMAIN_META[k].riskScore>80); if(openHigh)recs.push({id:'risk-'+openHigh,type:'Privacy',title:`Tighten ${DOMAIN_META[openHigh].name} policy`,text:`${DOMAIN_META[openHigh].name} carries a high prototype exposure weight. Locking or shortening retention can reduce modeled exposure with limited effect on low-risk domains.`,impact:'− exposure',action:'firewall'});
  const athTx=state.transactions.filter(t=>t.domain==='athletics');if(athTx.length>=2)recs.push({id:'ath-floor',type:'Pricing',title:'Test a higher Athletics floor',text:'Recent synthetic Athletics transactions cleared near or above the current floor. Scenario Lab can test a 15% increase before applying it.',impact:'+ price / − volume',action:'scenarios'});
  recs.push({id:'query',type:'Control',title:'Use ShadowQuery for minimum disclosure',text:'For compatible research questions, return a protected answer or score instead of transferring a row-level data package.',impact:'Zero-copy',action:'shadowquery'});
  state.recommendations=recs;save(); if(!silent)toast('Intelligence refreshed',`${recs.length} recommendations generated from current state`)
}

function renderChrome(){
  applyTheme(state.settings?.theme||'dark');
  const nav=appMode==='buyer'?NAV_BUYER:NAV_PERSONAL; $('#sideNav').innerHTML=nav.map(([sec,items])=>`<div class="nav-section">${sec}</div>${items.map(([id,label,icon,pill])=>`<button class="nav-item ${currentPage===id?'active':''}" data-action="nav" data-page="${id}"><span class="nav-ico">${icon}</span><span>${label}</span>${pill?`<span class="nav-pill">${pill}</span>`:''}</button>`).join('')}`).join('');
  $('#profileName').textContent=state.name;$('#profileMeta').textContent=state.kind==='demo'?'Demo · synthetic data':'Local profile';$('#avatar').textContent=state.initials||'DS';
  $$('.mode-btn').forEach(b=>b.classList.toggle('active',b.dataset.mode===appMode)); const unread=state.notifications.some(n=>!n.read);$('#notificationDot').style.display=unread?'block':'none';
}
function pageLabel(id){for(const [,items] of [...NAV_PERSONAL,...NAV_BUYER]){const f=items.find(x=>x[0]===id);if(f)return f[1]}return id}
function go(page){currentPage=page;renderChrome();$('#breadcrumbs').innerHTML=`<span>DataShadow</span><b>/</b><strong>${escapeHTML(pageLabel(page))}</strong>`;renderPage();if($('#guideDrawer')?.classList.contains('open'))renderGuideHub();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'})}

function pageHead(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`}
function sourceTag(type,label){return `<span class="source-tag ${type}">${type==='real'?'●':type==='public'?'◆':type==='sim'?'◇':'◈'} ${label}</span>`}
function metric(label,val,sub,tag=''){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${val}</div><div class="metric-sub">${sub}</div>${tag}</div>`}
function empty(icon,title,text,action='',actionLabel=''){return `<div class="empty"><div class="empty-icon">${icon}</div><h3>${title}</h3><p>${text}</p>${action?`<button class="btn primary" data-action="${action}">${actionLabel}</button>`:''}</div>`}
function renderPage(){
  ensureDemoAssets(); state.assets=(state.assets||[]).map(a=>revalueAsset(a));
  const routes={overview:renderOverview,vault:renderVault,twin:renderTwin,portfolio:renderPortfolio,marketplace:renderMarketplace,negotiation:renderNegotiation,shadowquery:renderShadowQuery,transactions:renderTransactions,receipts:renderReceipts,firewall:renderFirewall,policy:renderPolicy,shield:renderShield,risk:renderRisk,passport:renderPassport,intelligence:renderIntelligence,scenarios:renderScenarios,observatory:renderObservatory,graph:renderGraph,ledger:renderLedger,labs:renderLabs,technology:renderTechnology,patent:renderPatent,trust:renderTrust,about:renderAbout,buyer:renderBuyer,requestbuilder:renderRequestBuilder};
  $('#main').innerHTML=`<div class="page-enter">${(routes[currentPage]||renderOverview)()}</div>`; wirePage(); updateAssistantContext();
}

